LOGIN='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Remote Browser</title><style>body{background:#0a1220;color:#e6edf7;font:15px system-ui;min-height:100vh;display:grid;place-items:center;margin:0}main{width:min(310px,85vw);padding:28px;border:1px solid #35445d;border-radius:14px;background:#121e30}form{display:grid;gap:12px}input,button{font:inherit;padding:12px;border:1px solid #52647d;border-radius:7px}button{background:#aedaff;cursor:pointer}p{font-size:13px;color:#c1cfe0}</style><main><h2>Remote Browser</h2><p>Independent temporary browser</p><form method="post" action="/rb/login" autocomplete="on"><label for="user">Username</label><input id="user" name="username" autocomplete="username" inputmode="numeric" required><label for="pass">Password</label><input id="pass" name="password" type="password" autocomplete="current-password" required><button>Open browser</button></form><p id="status" role="status"></p></main><script>document.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=document.querySelector('button'),status=document.getElementById('status');button.disabled=true;status.textContent='Starting browser…';try{const response=await fetch('/rb/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('user').value,password:document.getElementById('pass').value})});const data=await response.json();if(!response.ok)throw Error(data.error||'Sign-in unavailable');location.replace('/rb/viewer');}catch(error){status.textContent=error.message;}finally{button.disabled=false;}};</script></html>'''


def viewer(nonce):
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Remote Browser</title><style>body{margin:0;background:#08101b;color:#eee;font:14px system-ui;display:flex;flex-direction:column;height:100vh}header{padding:8px 14px;display:flex;justify-content:space-between}iframe{border:0;width:100%;flex:1}button{cursor:pointer}</style><header><span id="status">Connecting…</span><button id="close">Close browser</button></header><iframe id="desktop" allow="autoplay; clipboard-read; clipboard-write; fullscreen" title="Remote Chromium"></iframe><script>
const lease=new WebSocket('wss://'+location.host+'/rb/lease/'''+nonce+'''');lease.onopen=()=>{document.getElementById('desktop').src='/rb/desktop/';document.getElementById('status').textContent='Remote Browser · Temporary session';};lease.onclose=()=>{document.getElementById('desktop').remove();document.getElementById('status').textContent='Session ended. Close this page or sign in again.';};setInterval(()=>{if(lease.readyState===1)lease.send('alive');},10000);addEventListener('pagehide',()=>lease.close());document.getElementById('close').onclick=()=>{lease.close();location.replace('/rb/');};</script></html>'''
